//
//  RawWebView.swift
//  Latchkey
//
//  SwiftUI bridge for the tab's owned WKWebView. Keeping the actual UIKit view
//  gives WebKit the exact frame SwiftUI assigns to the browser region and lets
//  its native keyboard, viewport, and safe-area handling work together.
//

import SwiftUI
import WebKit

#if canImport(UIKit)
struct RawWebView: UIViewRepresentable {
    @ObservedObject var model: BrowserViewModel
    /// What SwiftUI reports for this view's slot, measured by the GeometryReader
    /// in `BrowserView`. F9's confirmation step: compared against UIKit's own
    /// numbers below, because the three can disagree and only one of them is
    /// what WebKit turns into `env(safe-area-inset-*)`.
    var proxyInsets: EdgeInsets = EdgeInsets()
    @Environment(\.colorScheme) private var colorScheme

    func makeUIView(context: Context) -> WKWebView {
        let webView = model.makeWebView()
        applyThemeBackground(to: webView)
        return webView
    }

    func updateUIView(_ webView: WKWebView, context: Context) {
        model.attach(webView)
        applyThemeBackground(to: webView)
        logSafeArea(webView, context: context)
    }

    /// TEMPORARY (F9 §8): which of these is non-zero decides the fix, and the
    /// spec refuses to guess. `view` is what WebKit reads; `window` is the
    /// truth; `proxy` is what SwiftUI hands us. Logged only when it changes, so
    /// a resize storm cannot flood the node log.
    private func logSafeArea(_ webView: WKWebView, context: Context) {
        func fmt(_ i: UIEdgeInsets) -> String {
            "(t\(Int(i.top)) l\(Int(i.left)) b\(Int(i.bottom)) r\(Int(i.right)))"
        }
        let line = "safe-area: view=\(fmt(webView.safeAreaInsets))"
            + " window=\(fmt(webView.window?.safeAreaInsets ?? .zero))"
            + " proxy=(t\(Int(proxyInsets.top)) l\(Int(proxyInsets.leading))"
            + " b\(Int(proxyInsets.bottom)) r\(Int(proxyInsets.trailing)))"
        guard context.coordinator.lastSafeAreaLine != line else { return }
        context.coordinator.lastSafeAreaLine = line
        logger.log(line)
    }

    func makeCoordinator() -> Coordinator { Coordinator() }

    final class Coordinator {
        var lastSafeAreaLine = ""
    }

    /// WKWebView otherwise flashes its default white backing store before the
    /// first document paints. Set both the view and under-page colors so fresh
    /// startup and later new tabs match the active appearance consistently.
    private func applyThemeBackground(to webView: WKWebView) {
        let color: UIColor = colorScheme == .dark ? .black : .white
        webView.isOpaque = true
        webView.backgroundColor = color
        webView.scrollView.backgroundColor = color
        webView.underPageBackgroundColor = color
    }
}
#else
struct RawWebView: NSViewRepresentable {
    @ObservedObject var model: BrowserViewModel

    func makeNSView(context: Context) -> WKWebView {
        model.makeWebView()
    }

    func updateNSView(_ webView: WKWebView, context: Context) {
        model.attach(webView)
    }
}
#endif

