import Darwin
import Foundation
import TailscaleKit
import os

/// Unified-logging subsystem used for all Latchkey/libtailscale messages.
/// Filter for these in Console.app or with:
///
///   xcrun simctl spawn booted log stream \
///     --predicate 'subsystem == "net.lixom.latchkey"'
///
/// The members are `nonisolated` (and `OSLog` is `Sendable`) so they can be
/// read from `Logger.log`'s nonisolated context — libtailscale calls `log`
/// from its Go-backed threads, off the main actor.
enum LatchkeyLog {
    nonisolated static let subsystem = "net.lixom.latchkey"
    /// libtailscale / tsnet messages.
    nonisolated static let tsnet = OSLog(subsystem: subsystem, category: "tsnet")
}

// `nonisolated` (and `let`) so this Sendable global is callable from the
// nonisolated contexts that use it, including Go-backed callback threads.
nonisolated let logger = Logger()

struct Logger: TailscaleKit.LogSink {

    /// `LogSink.log` is called from libtailscale's (Go-backed) threads, which
    /// are off the main actor, so this must be `nonisolated`. It touches only
    /// `nonisolated` `Sendable` globals and the free `print`/`os_log`
    /// functions, so it is concurrency-safe.
    nonisolated func log(_ message: String) {
        // Scrub before anything is written anywhere (revision R1). Call sites
        // redact the URLs they log; this is the backstop for everything they
        // cannot see — an interpolated NSError's userInfo, libtailscale's own
        // messages arriving through this same sink, and future log lines.
        let message = LogRedaction.scrub(message)

        // Keep the pre-existing stdout behaviour — `xcodebuild test` captures
        // the app's stdout, so these `tsnet:` lines show up in the test log.
        print("tsnet: \(message)")

        // Also route into the unified logging system so the messages are
        // captured by `log stream` / Console.app / `log show` during UI tests
        // (where the app's stdout isn't always easy to read in real time).
        os_log("%{public}@", log: LatchkeyLog.tsnet, type: .default, message)

        // And keep a copy in memory so the in-app log viewer can show it. This
        // is the ONLY way to read these messages on a device that can't be
        // attached to a Mac (no `log stream`, no Console.app).
        LogRing.shared.append(message)

        // Upstream had a fourth sink here, `TailscaleLogging.log(message)`,
        // mirroring every app line into the process-wide logtail — whose
        // BaseURL is Tailscale's hosted log service. Removed per decision D1:
        // no app or tsnet logs leave the device. libtailscale's own upload is
        // disabled separately, inside the vendored Go code.
    }
}

/// A bounded in-memory ring buffer of the most recent log lines, so the app can
/// show its own logs (Settings → Logs). Every libtailscale/tsnet message and
/// every `logger.log(…)` call in the app funnels through `Logger.log`, so this
/// captures both.
///
/// Exists because the iPad that reported the "invalid URL" bug has a broken USB
/// port: `log stream`/Console.app aren't available, so on-device inspection is
/// the only diagnostic channel.
///
/// Thread-safety: `Logger.log` is called from libtailscale's Go-backed threads
/// as well as the main actor, so this is a `final class` guarded by an
/// `NSLock` rather than actor-isolated (callers are `nonisolated` and can't
/// await). Lock hold times are a few pointer writes.
nonisolated final class LogRing: @unchecked Sendable {
    nonisolated static let shared = LogRing()

    /// Stable identity lets SwiftUI retain existing rows when a live snapshot
    /// adds a line, instead of rebuilding every selectable Text view.
    nonisolated struct Entry: Identifiable, Equatable, Sendable {
        let id: UInt64
        let line: String
    }

    /// Lines and their counters must come from one lock acquisition. Besides
    /// being consistent, this keeps the UI from synchronously taking this lock
    /// twice for every refresh.
    nonisolated struct Snapshot: Sendable {
        let entries: [Entry]
        /// Entries appended since the most recent explicit clear.
        let total: Int
        let version: UInt64
        /// Identity of this in-memory ring object. It changes only if the
        /// process creates a new LogRing singleton.
        let incarnation: UUID
        /// Process-lifetime counters; unlike `total`, clear() does not reset them.
        let lifetimeAppends: UInt64
        let lifetimeWraps: UInt64
        let lifetimeClears: UInt64
        let lifetimeSocksLines: UInt64
        let lifetimeStatusRequests: UInt64
        let lifetimeBusErrors: UInt64
        let maxAppendsPerSecond: UInt64
        let spinTrips: UInt64
        let oldestID: UInt64?
        let newestID: UInt64?
    }

    /// Keep well over the 1000 lines needed to see a full connect + browse
    /// cycle; each entry is short, so a few thousand costs little memory.
    private let capacity = 4000
    private let lock = NSLock()
    private let incarnation = UUID()
    private var entries: [Entry] = []
    /// Index of the oldest entry once the buffer has wrapped.
    private var start = 0

/// One full-screen web view, plus the two things allowed to appear over it:
/// the log viewer and the tailnet login banner.
private struct DashboardContent: View {
    let workspace: Workspace
    @ObservedObject var homePage: HomePage
    @ObservedObject var model: TSNetModel
    @ObservedObject var tab: BrowserTab
    @ObservedObject var statusViewModel: StatusViewModel
    @ObservedObject var session: SessionManager
    let onSettings: () -> Void
    @State private var showingGatewayPicker = false
    /// A gateway chosen in the Find sheet, applied once the sheet is gone:
    /// the new gateway's page may ask for a token at once, and two sheets
    /// cannot overlap (M5 review; the same rule as Settings, M4).
    @State private var pendingGateway: String?

    var body: some View {
        Group {
            if homePage.hasGateway {
                NavigationStack {
                    gatewayContent
#if canImport(UIKit)
                        .toolbar(.hidden, for: .navigationBar)
#endif
                }
            } else {
                // First run (M5): no gateway yet. Its own navigation stack,
                // not nested in the dashboard's toolbar-less one (M5 review).
                GatewayPickerView(discovery: workspace.discovery, model: model, savedHost: nil,
                                  autoSelectSingle: true,
                                  onSelect: { workspace.selectGateway($0) })
            }
        }
        // The page owns the full screen, including the bottom safe area.
        // Without this the root layout leaves an app-background strip beneath
        // dark web content.
        .ignoresSafeArea(.container, edges: .bottom)
        .overlay(alignment: .topTrailing) {
            settingsAffordance
        }
        .overlay(alignment: .topLeading) {
            // Its own view, observing the BrowserViewModel directly: this view
            // observes the BrowserTab, which does not republish the view
            // model's changes, so reading the flag here would never update.
            ReturnToDashboardAffordance(model: tab.viewModel)
        }
        .overlay(alignment: .top) {
            // The way back to the sheet after closing it: the page's own
            // banner is hidden (R22), so this is the only sign-in control.
            // Keyed on the sheet being ON SCREEN, not requested: a deferred
            // request must not hide the only way in (M4 review).
            // Not while the node itself is down: its banner comes first, and
            // no dashboard sign-in can work until it is back (R31 review).
            if session.state == .needsToken, !session.isTokenSheetOnScreen,
               !statusViewModel.needsAuth, !statusViewModel.needsMachineAuth {
                Button {
                    session.isTokenSheetPresented = true
                } label: {
                    Label("Signed out — Sign in", systemImage: "person.crop.circle.badge.exclamationmark")
                        .font(.subheadline.weight(.semibold))
                        .padding(.horizontal, 14)
                        .padding(.vertical, 8)
                        .background(.thinMaterial, in: Capsule())
                }
                .buttonStyle(.plain)
                .padding(.top, 4)
                .accessibilityIdentifier("session-signin-button")
            }
        }
        // M5.5: re-probe when the chosen gateway is unreachable.
        .sheet(isPresented: $showingGatewayPicker, onDismiss: {
            if let origin = pendingGateway {
                pendingGateway = nil
                workspace.selectGateway(origin)
            }
        }) {
            GatewayPickerView(discovery: workspace.discovery, model: model,
                              savedHost: URL(string: homePage.url)?.host(),
                              autoSelectSingle: false,
                              sweepOnAppear: true,
                              onSelect: { origin in
                                  pendingGateway = origin
                                  showingGatewayPicker = false
                              },
                              onCancel: { showingGatewayPicker = false })
        }
#if LATCHKEY_TEST_HOOKS
        .overlay(alignment: .bottomLeading) {
            // For UI tests: how many times the connecting block became visible
            // for this tab (F4 §4.7). A block that flashes up and away between
            // two looks is invisible to a poll but not to this number — which is
            // the failure mode the 300 ms delay could introduce.
            Text("connecting-shown:\(tab.viewModel.connectingShownCount)")
                .accessibilityIdentifier("page-connecting-shown-count")
                .opacity(0.01)
        }
        .overlay(alignment: .bottom) {
            // For UI tests: how many times the page asked for a token, so a
            // sheet that flashes up and away between two looks is caught.
            Text("\(session.authRequiredEvents)")
                .accessibilityIdentifier("session-auth-required-count")
                .opacity(0.01)
        }
#endif
        .overlay(alignment: .bottomTrailing) {
            // A concrete accessibility element for UI automation. An
            // identifier applied to a container view is not reliably surfaced.
            Text("Connected Browser")
                .accessibilityIdentifier("connected-browser")
                .opacity(0.01)
        }
        .overlay(alignment: .bottomLeading) {
            if TSNetManager.tcpChaosTestRequested(),
               let status = workspace.model.tcpChaosTestStatus {
                Text(status)
                    .accessibilityIdentifier("tcp-chaos-test-status")
                    .opacity(0.01)
            }
        }
        // With the toolbar gone, these are the hardware-keyboard paths to
        // Settings (which owns the log viewer) and to a reload. Defined here
        // so they stay available regardless of what has focus inside the web
        // content.
        .background {
#if !os(macOS)
            Group {
                Button("Settings") { onSettings() }
                    .keyboardShortcut(",", modifiers: .command)
                Button("Reload") { tab.viewModel.reload() }
                    .keyboardShortcut("r", modifiers: .command)
            }
            .hidden()
#endif
        }
    }

    /// The one piece of app chrome the dashboard keeps.
    ///
    /// Deleting the browser toolbar (PLAN §1.5) also deleted the only gear
    /// button reachable after connecting — the other one lives in the
    /// connection gate, which is gone by then. That left Settings, and through
    /// it the log viewer and the routing diagnostic, reachable ONLY by ⌘, on a
    /// hardware keyboard: unreachable on an iPhone. §1.9 says keep the
    /// diagnostics, so something has to be tappable.
    ///
    /// Kept deliberately small and faint so it reads as an affordance rather
    /// than chrome, and placed top-trailing where KiroCrew's own header has no
    /// controls. It sits inside the safe area, so it does not fight the status
    /// bar.
    ///
    /// The fade is on the label, not the button: over the web view, a button
    /// with `.opacity` below 1 gets no taps at all (not even with a
    /// `contentShape`), so this gear was dead from M1 until R29's diagnostics
    /// test tapped it.
    private var settingsAffordance: some View {
        Button(action: onSettings) {
            Image(systemName: "gearshape.fill")
                .font(.system(size: 15, weight: .semibold))
                .foregroundStyle(.secondary)
                .padding(7)
                .background(.thinMaterial, in: Circle())
                .opacity(0.45)
        }
        .buttonStyle(.plain)
        .padding(.trailing, 10)
        .padding(.top, 4)
        .accessibilityIdentifier("settings-button")
        .accessibilityLabel("Settings")
    }

    private var gatewayContent: some View {
        VStack(spacing: 0) {
            // The node's own trouble first, in the layout rather than over it
            // (R31 review): an overlay covered the gateway banner's buttons and
            // was itself covered by the sign-in capsule.
            if statusViewModel.needsAuth {
                // Mid-session NeedsLogin -- the node key expired, or was
                // expired by an admin (R31): Login re-authenticates in place.
                LoginBanner(
                    authSessionEndedGeneration: statusViewModel.authSessionEndedGeneration,
                    onLogin: { statusViewModel.showAuth() }
                )
            } else if statusViewModel.needsMachineAuth {
                MachineAuthBanner()
            }
            if homePageAvailability == .unavailable {
                GatewayUnreachableBanner(onSettings: onSettings,
                                         onFindGateways: { showingGatewayPicker = true })
            }
            // The one picker presentation lives here (F4 §4.7), so Find, Change,
            // the connecting hint's button and the error page's all go through
            // it and two sheets can never overlap (M5 review). The load is
            // stopped first, which moves the page to a failed state with cause
            // `stopped` — so cancelling the picker lands on an error page with
            // Try again, never back on a blank web view.
            BrowserView(model: tab.viewModel,
                        gatewayMissing: homePageAvailability == .unavailable,
                        onChooseGateway: {
                            tab.viewModel.stopForGatewayChange()
                            showingGatewayPicker = true
